function validate([creators, ids, views]) {
  const n = creators.length;
  if (n < 1 || n > 100000) return 'There must be 1 to 100000 videos.';
  if (ids.length !== n || views.length !== n) return 'creators, ids and views must have the same length.';
  const word = /^[a-z]{1,5}$/;
  if (creators.some(c => typeof c !== 'string' || !word.test(c))) return 'Each creator is 1 to 5 lowercase letters.';
  if (ids.some(c => typeof c !== 'string' || !word.test(c))) return 'Each id is 1 to 5 lowercase letters.';
  if (views.some(v => !Number.isInteger(v) || v < 0 || v > 100000)) return 'Each views value is an integer from 0 to 10^5.';
  return null;
}

