function mostPopularCreator(creators, ids, views) {
  const popularity = new Map();
  const bestVideo = new Map();
  let maxPopularity = 0;

  for (let i = 0; i < creators.length; i++) {
    const creator = creators[i];
    const total = (popularity.get(creator) ?? 0) + views[i];
    popularity.set(creator, total);
    maxPopularity = Math.max(maxPopularity, total);

    const best = bestVideo.get(creator);
    const moreViews = best === undefined || views[i] > views[best];
    const smallerTie = best !== undefined && views[i] === views[best] && ids[i] < ids[best];
    if (moreViews || smallerTie) {
      bestVideo.set(creator, i);
    }
  }

  const answer = [];
  for (const [creator, total] of popularity) {
    if (total === maxPopularity) {
      answer.push([creator, ids[bestVideo.get(creator)]]);
    }
  }
  return answer;
}

