function mostPopularCreator(creators, ids, views) {
  const names = [...new Set(creators)];
  const sums = names.map(name => creators.reduce((acc, c, i) => acc + (c === name ? views[i] : 0), 0));
  const top = Math.max(...sums);
  const result = [];
  names.forEach((name, j) => {
    if (sums[j] !== top) return;
    const videos = creators.map((c, i) => i).filter(i => creators[i] === name);
    videos.sort((x, y) => views[y] - views[x] || (ids[x] < ids[y] ? -1 : ids[x] > ids[y] ? 1 : 0));
    result.push([name, ids[videos[0]]]);
  });
  return result;
}

