function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const word = (letters, maxLen) => {
    let w = '';
    const len = pick(1, maxLen);
    for (let i = 0; i < len; i++) w += letters[pick(0, letters.length - 1)];
    return w;
  };
  if (size === 'small') {
    const n = pick(1, 8);
    const people = Array.from({ length: pick(1, 4) }, () => word('abc', 2));
    const creators = Array.from({ length: n }, () => people[pick(0, people.length - 1)]);
    const ids = Array.from({ length: n }, () => word('xyz', 2));
    const views = Array.from({ length: n }, () => pick(0, 4));
    return [creators, ids, views];
  }
  const n = 2000;
  const people = Array.from({ length: pick(2, 60) }, () => word('abcdefghij', 5));
  const maxView = [3, 100, 100000][pick(0, 2)];
  const creators = Array.from({ length: n }, () => people[pick(0, people.length - 1)]);
  const ids = Array.from({ length: n }, () => word('pqrst', 5));
  const views = Array.from({ length: n }, () => pick(0, maxView));
  return [creators, ids, views];
}
